29: async function ask(question) {
30:   const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
31:   const answer = await rl.question(question);
32:   rl.close();
33:   return answer.trim();
34: }
35: 
36: function appName(dir) {
37:   if (flags.app) return flags.app;
38:   return detect(dir).name;
39: }
40: 
41: function fmtSize(b) {
42:   return b < 1024 ? `${b} B` : b < 1048576 ? `${Math.round(b / 1024)} KB` : `${(b / 1048576).toFixed(1)} MB`;
43: }
