45: // The [inputs] schema lives in the local small.toml; running someone else's app
46: // from elsewhere has no schema to validate against.
47: function localConfig(name) {
48:   const p = path.join(process.cwd(), 'small.toml');
49:   if (!fs.existsSync(p)) return null;
50:   const cfg = toml.parse(fs.readFileSync(p, 'utf8'));
51:   const local = cfg.name || path.basename(process.cwd()).toLowerCase().replace(/[^a-z0-9-]/g, '-');
52:   return local === name ? cfg : null;
53: }
