64: async function downloadOutputs(name, dir) {
65:   const { runs } = await call('GET', `/api/runs?app=${encodeURIComponent(name)}`);
66:   const last = (runs || []).find((r) => r.status === 'finished'); // list is newest-first
67:   if (!last) throw new Error(`no finished runs for ${name}`);
68:   const { outputs } = await call('GET', `/api/runs/${encodeURIComponent(last.run_id)}/outputs`);
69:   if (!(outputs || []).length) return console.log(`run ${last.run_id} produced no outputs`);
70:   for (const o of outputs) {
71:     if (o.name.includes('..')) continue; // never let a server-supplied name walk out of dir
72:     const dest = path.join(dir, o.name);
73:     fs.mkdirSync(path.dirname(dest), { recursive: true });
74:     fs.writeFileSync(dest, await fetchRaw(`/api/runs/${encodeURIComponent(last.run_id)}/outputs/${encodeURIComponent(o.name)}`));
75:     console.log(`✓ wrote ${dest} (${fmtSize(o.size)})`);
76:   }
77: }
